"""Network side of the reconciliation: fetch order pages and customer records.

Usage:
  recon.py orders    <outdir>                      fetch every order page into <outdir>/page-NNN.json
  recon.py customers <ids.json> <cache.json>       fetch each listed customer once into <cache.json>

All requests go through Client.request(), which:
  * waits as long as the service asks on HTTP 429 (Retry-After header / retry_after body field),
  * fetches a fresh token when a request is rejected as unauthenticated,
  * repeats a request after any transient failure instead of giving up,
  * appends every non-200 event to the event log for later inspection.
"""
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
EVENT_LOG = os.path.join(DATA, "events.jsonl")


def raw(method, path, token=None, timeout=30):
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read()


def retry_after_seconds(headers, body):
    """Seconds the service asked us to wait: header and body field, whichever is larger."""
    asked = []
    h = headers.get("Retry-After")
    if h is not None:
        try:
            asked.append(float(h))
        except ValueError:
            pass
    try:
        b = json.loads(body).get("retry_after")
        if isinstance(b, (int, float)):
            asked.append(float(b))
    except (ValueError, AttributeError):
        pass
    return max(asked) if asked else None


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "rate_limited": 0, "waited_s": 0.0, "tokens": 0,
                      "auth_rejections": 0, "transient": 0, "not_found": 0}

    def log(self, **kw):
        kw["ts"] = time.strftime("%H:%M:%S")
        with open(EVENT_LOG, "a") as f:
            f.write(json.dumps(kw) + "\n")

    def request(self, method, path, auth=True, not_found_ok=False):
        """Return parsed JSON for a 200, or None for a 404 when not_found_ok. Retries everything else."""
        auth_failures = 0
        transient = 0
        notfound_seen = 0
        while True:
            if auth and self.token is None:
                self.token = self.request("POST", "/token", auth=False)["token"]
                self.stats["tokens"] += 1
                self.log(event="new_token", token=self.token)
            try:
                status, headers, body = raw(method, path, self.token if auth else None)
            except (urllib.error.URLError, OSError) as e:
                transient += 1
                self.stats["transient"] += 1
                self.log(event="network_error", path=path, error=repr(e))
                if transient > 10:
                    raise
                time.sleep(min(0.5 * transient, 5))
                continue
            self.stats["requests"] += 1
            text = body.decode("utf-8", "replace")
            if status == 200:
                try:
                    return json.loads(text)
                except ValueError:
                    transient += 1
                    self.stats["transient"] += 1
                    self.log(event="bad_json", path=path, body=text[:200])
                    if transient > 10:
                        raise RuntimeError(f"{path}: 200 with unparseable body: {text[:200]!r}")
                    time.sleep(0.5)
                    continue
            if status == 429:
                wait = retry_after_seconds(headers, body)
                if wait is None:
                    wait = 5.0
                    self.log(event="rate_limited_no_hint", path=path, body=text[:200])
                self.stats["rate_limited"] += 1
                self.stats["waited_s"] += wait
                self.log(event="rate_limited", path=path, wait=wait)
                time.sleep(wait + 0.1)
                continue
            if status in (401, 403) and auth:
                auth_failures += 1
                self.stats["auth_rejections"] += 1
                self.log(event="auth_rejected", path=path, status=status, body=text[:200], token=self.token)
                if auth_failures > 5:
                    raise RuntimeError(f"{path}: rejected {auth_failures} times in a row even with fresh tokens")
                self.token = None
                continue
            if status == 404 and not_found_ok:
                # Confirm it is not a one-off before believing it.
                notfound_seen += 1
                if notfound_seen >= 3:
                    self.stats["not_found"] += 1
                    self.log(event="not_found", path=path, body=text[:200])
                    return None
                time.sleep(0.3)
                continue
            if status >= 500:
                transient += 1
                self.stats["transient"] += 1
                self.log(event="server_error", path=path, status=status, body=text[:200])
                if transient > 10:
                    raise RuntimeError(f"{path}: HTTP {status} {transient} times: {text[:200]!r}")
                time.sleep(min(0.5 * transient, 5))
                continue
            self.log(event="unexpected_status", path=path, status=status, body=text[:300])
            raise RuntimeError(f"{path}: unexpected HTTP {status}: {text[:300]!r}")


def valid_page(d, want_page):
    return (isinstance(d, dict) and d.get("page") == want_page and isinstance(d.get("items"), list)
            and isinstance(d.get("total_pages"), int) and "next" in d)


def fetch_orders(outdir):
    os.makedirs(outdir, exist_ok=True)
    c = Client()
    page = 1
    total_pages = None
    while True:
        for attempt in range(1, 8):
            d = c.request("GET", f"/orders?page={page}")
            if valid_page(d, page):
                break
            c.log(event="invalid_page", page=page, attempt=attempt, body=json.dumps(d)[:300])
            time.sleep(0.5)
        else:
            raise RuntimeError(f"page {page}: never returned a valid page body")
        if total_pages is None:
            total_pages = d["total_pages"]
        elif d["total_pages"] != total_pages:
            c.log(event="total_pages_changed", page=page, was=total_pages, now=d["total_pages"])
            print(f"  NOTE total_pages changed {total_pages} -> {d['total_pages']} at page {page}")
            total_pages = d["total_pages"]
        with open(os.path.join(outdir, f"page-{page:03d}.json"), "w") as f:
            json.dump(d, f)
        print(f"page {page}/{total_pages}: {len(d['items'])} items, next={d['next']}  "
              f"[req={c.stats['requests']} 429s={c.stats['rate_limited']} tokens={c.stats['tokens']}]", flush=True)
        expected_next = f"/orders?page={page + 1}" if page < total_pages else None
        if d["next"] != expected_next:
            print(f"  NOTE next={d['next']!r}, expected {expected_next!r}")
            c.log(event="unexpected_next", page=page, next=d["next"], expected=expected_next)
        if page >= total_pages and d["next"] is None:
            break
        page += 1
        if page > total_pages + 5:
            raise RuntimeError("walked past total_pages without reaching a last page")
    print("done:", json.dumps(c.stats))


def fetch_customers(ids_path, cache_path):
    with open(ids_path) as f:
        ids = json.load(f)
    cache = {}
    if os.path.exists(cache_path):
        with open(cache_path) as f:
            cache = json.load(f)
    c = Client()
    todo = [i for i in ids if i not in cache]
    print(f"{len(ids)} customers needed, {len(cache)} cached, {len(todo)} to fetch", flush=True)
    for n, cid in enumerate(todo, 1):
        rec = c.request("GET", f"/customers/{cid}", not_found_ok=True)
        cache[cid] = rec  # None means confirmed unknown (404)
        with open(cache_path, "w") as f:
            json.dump(cache, f)
        if n % 10 == 0 or n == len(todo):
            print(f"  {n}/{len(todo)} fetched  [req={c.stats['requests']} 429s={c.stats['rate_limited']} "
                  f"tokens={c.stats['tokens']}]", flush=True)
    print("done:", json.dumps(c.stats))


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "orders":
        fetch_orders(sys.argv[2])
    elif len(sys.argv) >= 4 and sys.argv[1] == "customers":
        fetch_customers(sys.argv[2], sys.argv[3])
    else:
        print(__doc__)
        sys.exit(2)

