"""Request the page just past total_pages to confirm the listing really ends at page 30.
Waits as told on 429 and fetches a new token on 401, like the main fetcher."""
import json
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


def call(method, path, token=None):
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()


token = None
for _ in range(20):
    if token is None:
        status, body = call("POST", "/token")
        token = json.loads(body)["token"]
    status, body = call("GET", "/orders?page=31", token)
    if status == 429:
        time.sleep(json.loads(body).get("retry_after", 1) + 0.1)
        continue
    if status == 401:
        token = None
        continue
    print("page 31 ->", status, body[:400])
    break

